import atexit
import threading
import time
import logging
from typing import Tuple, Any, Callable

from flask import Flask, render_template, Response, request, jsonify

import config
from camera import Camera
import mail_config  # Assuming this is your email configuration module

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize Flask app
app = Flask(__name__)

# Initialize camera
try:
    camera = Camera()
    camera.initialize(config.CAMERA_TYPE)
    camera.vs.flip = config.CAMERA_FLIP
    logging.info("Camera initialized successfully.")
except Exception as e:
    logging.error(f"Error initializing camera: {e}")
    exit(1)  # Exit if camera initialization fails


# Initialize last email send time
last_email_send = 0

# Function to get camera frame as JPEG image
def get_frame() -> bytes:
    """Captures a frame from the camera and returns it as JPEG."""
    try:
        frame = camera.get_frame()
        return frame
    except Exception as e:
        logging.error(f"Error capturing frame: {e}")
        return b""  # Return empty bytes on error


# HTML Templates
@app.route('/')
def index() -> str:
    """Renders the main index HTML page."""
    return render_template('index.html', classifiers=config.CLASSIFIERS, classifier_name=config.classifier_name)


@app.route('/video_feed')
def video_feed() -> Response:
    """Provides the video feed for the web interface."""
    return Response(gen(camera), mimetype='multipart/x-mixed-replace; boundary=frame')


def gen(camera: Camera) -> Any:  # Generator type
    """Generator function to continuously provide video frames."""
    try:
        while True:
            frame = get_frame()
            if frame:  # Check if frame is not empty
                yield (b'--frame\r\n'
                       b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n\r\n')
    except Exception as e:
        logging.error(f"Error in video feed generator: {e}")



# ... (rest of the Flask routes and helpers - functional style implementation)


def check_for_objects() -> None:
    """Continuously checks for objects and sends email notifications."""
    last_time = time.time()
    while True:
        try:
            if config.classifier_name == 'motion_detector':
                frame, detected = camera.get_object_with_basic_motion_detection()
            else:
                frame, detected = camera.get_object(config.classifier)

            if detected and config.send_email_notifications and (time.time() - last_time > config.email_send_interval):
                try:
                    mail_config.send_email(frame, config)
                    last_time = time.time()
                except Exception as e:
                    logging.error(f"Error sending email: {e}")

        except Exception as e:
            logging.error(f"Error in check_for_objects: {e}")
            time.sleep(1)  # Prevent excessive logging in case of continuous errors



if __name__ == '__main__':
    # Start the object detection/email thread
    detection_thread = threading.Thread(target=check_for_objects)
    detection_thread.daemon = True  # Allow the main thread to exit even if this is running
    detection_thread.start()

    # Start the Flask app
    try:
        app.run(host='0.0.0.0', port=config.PORT, debug=False, threaded=True, use_reloader=False)
    except Exception as e:
        logging.error(f"Error running Flask app: {e}")
    finally:
        logging.info("Exiting program.")

