#!/usr/bin/env python3

import RPi.GPIO as GPIO
import speech_recognition as sr
import time
import datetime
import os
import signal
import sys
import random

# Configuration
LIGHTS_PIN = 17
DHT_PIN = 4
CAMERA_RESOLUTION = (640, 480)
WAKE_WORD = "Greenhouse"

# Global flag for graceful shutdown
shutdown_flag = False

# Function to handle graceful shutdown
def signal_handler(sig, frame):
    global shutdown_flag
    shutdown_flag = True
    print("Shutting down gracefully...")

# Register signal handler for SIGINT and SIGTERM
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Initialize GPIO (or simulate if unavailable)
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHTS_PIN, GPIO.OUT)
    print("GPIO initialized successfully.")
except Exception as e:
    print(f"GPIO initialization failed: {e}. Simulating GPIO mode.")
    GPIO = None  # Simulate GPIO mode

# Initialize DHT11 sensor (or simulate if unavailable)
try:
    import adafruit_dht
    dht_device = adafruit_dht.DHT11(DHT_PIN)
    print("DHT11 sensor initialized successfully.")
except ImportError:
    print("adafruit_dht library not found. Simulating temperature reading.")
    dht_device = None

# Initialize camera (or simulate if unavailable)
try:
    from picamera2 import Picamera2
    picam2 = Picamera2()
    picam2.configure(picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": CAMERA_RESOLUTION}))
    picam2.start()
    print("Camera initialized successfully.")
except ImportError:
    print("picamera2 library not found. Simulating camera capture.")
    picam2 = None

# Function to turn lights on
def turn_lights_on():
    if GPIO:
        GPIO.output(LIGHTS_PIN, GPIO.HIGH)
        print("Lights turned on.")
    else:
        print("Simulating lights on.")

# Function to turn lights off
def turn_lights_off():
    if GPIO:
        GPIO.output(LIGHTS_PIN, GPIO.LOW)
        print("Lights turned off.")
    else:
        print("Simulating lights off.")

# Function to read temperature
def read_temperature():
    if dht_device:
        try:
            temperature_c = dht_device.temperature
            if temperature_c is not None:
                return temperature_c
            else:
                print("Failed to read temperature from DHT11 sensor.")
                return None
        except RuntimeError as error:
            # Errors happen fairly often, DHT's are hard to read, just keep going
            print(error.args[0])
            return None
        except Exception as error:
            dht_device.exit()
            raise error
    else:
        # Simulate temperature reading
        print("Simulating temperature reading.")
        return random.uniform(15, 35)

# Function to take a picture
def take_picture():
    if picam2:
        try:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            picam2.capture_file(filename)
            print(f"Picture saved as {filename}")
        except Exception as e:
            print(f"Error taking picture: {e}")
    else:
        print("Simulating picture capture.")

# Main function
def main():
    r = sr.Recognizer()
    mic = sr.Microphone()

    with mic as source:
        r.adjust_for_ambient_noise(source)

    while not shutdown_flag:
        try:
            with mic as source:
                print("Say 'Greenhouse' to start...")
                audio = r.listen(source, timeout=5) # Listen for 5 seconds

            try:
                text = r.recognize_google(audio).lower()
                print(f"You said: {text}")

                if WAKE_WORD in text:
                    if "turn on the lights" in text:
                        turn_lights_on()
                    elif "turn off the lights" in text:
                        turn_lights_off()
                    elif "what is the temperature" in text:
                        temperature = read_temperature()
                        if temperature is not None:
                            print(f"The temperature is {temperature:.1f}°C")
                    elif "take a picture" in text:
                        take_picture()
                    else:
                        print("Unknown command.")

            except sr.UnknownValueError:
                print("Could not understand audio")
            except sr.RequestError as e:
                print(f"Could not request results from Google Speech Recognition service; {e}")

        except sr.WaitTimeoutError:
            print("No speech detected.")
        except Exception as e:
            print(f"An error occurred: {e}")

    # Cleanup resources
    if GPIO:
        GPIO.cleanup()
    if picam2:
        picam2.close()

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Exiting program.")

