import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Configuration constants
I2C_ADDRESS_MULTIPLEXER = 0x70
BME280_ADDRESS = 0x76
TSL2591_ADDRESS = 0x29
READ_INTERVAL_SECONDS = 2

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=I2C_ADDRESS_MULTIPLEXER)
        return multiplexer
    except Exception as e:
        print(f"Error initializing multiplexer: {e}")
        return None

def initialize_sensors(multiplexer):
    """Initialize the BME280 and TSL2591 sensors."""
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0], address=BME280_ADDRESS)
        tsl2591_sensor = adafruit_tsl2591.TSL2591(multiplexer[1], address=TSL2591_ADDRESS)
        return bme280_sensor, tsl2591_sensor
    except Exception as e:
        print(f"Error initializing sensors: {e}")
        return None, None

def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Read data from the BME280 and TSL2591 sensors."""
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        light_intensity = tsl2591_sensor.lux
        return temperature, humidity, light_intensity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None

def display_sensor_data(temperature, humidity, light_intensity):
    """Print the sensor data to the console."""
    if all(v is not None for v in [temperature, humidity, light_intensity]):
        print(f"Temperature: {temperature:.2f} °C, Humidity: {humidity:.2f} %, Light Intensity: {light_intensity:.2f} lux")

def main():
    """Main function to read and display sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor, tsl2591_sensor = initialize_sensors(multiplexer)
    if not all(v is not None for v in [bme280_sensor, tsl2591_sensor]):
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for adafruit_tca9548a or the sensors, but good practice to include a finally block
        print("Program finished.")

if __name__ == "__main__":
    main()

