#!/usr/bin/env python3

# Script Name: cpu_temp_monitor.py
# Description: Reads and prints the CPU temperature from the Raspberry Pi.
# Author: Bard
# Date: 2023-10-27
# Hardware Requirements: Raspberry Pi 4 Model B
# Software Requirements: Python 3, gpiozero

import time
from gpiozero import CPUTemperature

def read_cpu_temperature():
    """Reads the CPU temperature and prints it to the console."""
    try:
        cpu = CPUTemperature()
        temperature = cpu.temperature
        print(f"CPU Temperature: {temperature:.2f} °C")
    except FileNotFoundError:
        print("Error: Could not read CPU temperature.  Check /sys/class/thermal/thermal_zone0/temp exists.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def main():
    """Main function to continuously read and print CPU temperature."""
    try:
        while True:
            read_cpu_temperature()
            time.sleep(5)  # Wait 5 seconds
    except KeyboardInterrupt:
        print("\nProgram terminated.")
    except Exception as e:
        print(f"An error occurred during program execution: {e}")

if __name__ == "__main__":
    main()

