#!/usr/bin/env python3

"""
Reads pressure from a BMP280 sensor and calculates relative altitude using a functional approach.
"""

import time
import logging
from typing import List, Tuple

try:
    from smbus2 import SMBus
except ImportError:
    from smbus import SMBus
from bmp280 import BMP280, CalibrationError


# Configure logging
logging.basicConfig(
    level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s"
)

# Constants
BASELINE_SAMPLE_SIZE = 100
BASELINE_TRIM_PERCENTAGE = 0.25  # 25% from each end
I2C_BUS = 1
BMP280_ADDRESS = 0x76
# Sensor's default address, change if the address is changed during the setup
DEFAULT_ADDRESS = 0x76
# Sensor's default chip ID, change if the chip ID is different during the setup
DEFAULT_CHIP_ID = 0x58


def initialize_bmp280(bus: SMBus, address: int = BMP280_ADDRESS) -> BMP280:
    """Initializes the BMP280 sensor with error handling."""
    try:
        bmp280 = BMP280(i2c_dev=bus, i2c_addr=address)
        if bmp280.get_calib_param() is None:  # Check if calibration data is valid
            raise CalibrationError("Failed to retrieve calibration data.")
        return bmp280
    except (OSError, CalibrationError) as e:
        raise RuntimeError(f"BMP280 initialization failed: {e}")


def read_pressure(bmp280: BMP280) -> float:
    """Reads pressure from the BMP280 sensor with error handling."""
    try:
        return bmp280.get_pressure()
    except OSError as e:
