# bmp280_altitude_logging_rpizero.py
# Reads temperature and pressure from a BMP280 sensor and logs altitude changes.
# Optimized for Raspberry Pi Zero W in an industrial automation context.

import time
import board
import busio
import adafruit_bmp280

# Configuration
I2C_ADDRESS = 0x76  # Default BMP280 I2C address
SEA_LEVEL_PRESSURE = 1013.25  # Standard sea level pressure in hPa
LOG_FILE = 'altitude_log.txt'
READ_INTERVAL_SECONDS = 1

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=I2C_ADDRESS)
        sensor.sea_level_pressure = SEA_LEVEL_PRESSURE
        return sensor
    except Exception as e:
        print(f"Error initializing BMP280 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads pressure and altitude from the sensor."""
    try:
        pressure = sensor.pressure
        altitude = sensor.altitude
        return pressure, altitude
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def log_altitude(pressure, altitude):
    """Logs the altitude reading to a file."""
    if pressure is not None and altitude is not None:
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f'{timestamp} - Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters\n'
        try:
            with open(LOG_FILE, 'a') as logfile:
                logfile.write(log_entry)
        except Exception as e:
            print(f"Error writing to log file: {e}")

def main():
    """Main function to read sensor data and log altitude."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            pressure, altitude = read_sensor_data(sensor)
            if pressure is not None and altitude is not None:
                print(f'Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters')
                log_altitude(pressure, altitude)
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or BMP280 in this library,
        # but good practice to include a finally block for potential future expansion.
        print("Exiting program.")

if __name__ == "__main__":
    main()

