import urllib.request
import adafruit_dht
import board

# Configuration
SERVER_URL = "http://127.0.0.1:5000/data"
SENSOR_PIN = board.D4  # GPIO4 (physical pin 7)
READ_INTERVAL_SECONDS = 5

# Initialize DHT sensor
dht_sensor = adafruit_dht.DHT11(SENSOR_PIN)

def get_sensor_data():
    """Reads temperature and humidity from the DHT sensor."""
    try:
        temperature = dht_sensor.temperature
        humidity = dht_sensor.humidity
        return temperature, humidity
    except RuntimeError as e:
        print(f"Sensor read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error: {e}")
        return None, None

def send_data_to_server(temperature, humidity):
    """Sends temperature and humidity data to the server."""
    if temperature is not None and humidity is not None:
        data = {"temperature": temperature, "humidity": humidity}
        try:
            req = urllib.request.Request(SERVER_URL, data=json.dumps(data).encode('utf-8'), method='POST', headers={'Content-Type': 'application/json'})
            with urllib.request.urlopen(req) as response:
                print(f"Data sent. Server response: {response.status}")
        except urllib.error.URLError as e:
            print(f"Connection error: {e}")
        except Exception as e:
            print(f"Error sending data: {e}")
    else:
        print("Invalid sensor data, not sending.")

def main():
    """Main function to read sensor data and send it to the server."""
    try:
        while True:
            temperature, humidity = get_sensor_data()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%")
                send_data_to_server(temperature, humidity)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for adafruit_dht, but good practice to include
        print("Program finished.")

if __name__ == "__main__":
    main()

