# Environmental monitoring script for Raspberry Pi 4
# Reads temperature and humidity from a UART sensor

import serial
import time

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Alert thresholds
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0


def read_sensor_data(serial_connection):
    """Reads a line from the serial port and parses it."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            fields = line.split(',')
            if len(fields) == 2:
                try:
                    temperature = float(fields[0])
                    humidity = float(fields[1])
                    return temperature, humidity
                except ValueError:
                    print("Error: Could not convert sensor data to numbers.")
                    return None, None
            else:
                print("Error: Incorrect number of fields in sensor data.")
                return None, None
        else:
            return None, None
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
        return None, None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None, None


def process_data(temperature, humidity):
    """Processes the sensor data and prints the readings."""
    if temperature is not None and humidity is not None:
        print(f'Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %')
        if temperature > TEMP_THRESHOLD:
            print('Alert: High temperature!')
        if humidity > HUMIDITY_THRESHOLD:
            print('Alert: High humidity!')


def main():
    """Main function to read and process sensor data."""
    serial_connection = None
    try:
        # Initialize serial connection
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to serial port {SERIAL_PORT}")

        while True:
            temperature, humidity = read_sensor_data(serial_connection)
            if temperature is not None and humidity is not None:
                process_data(temperature, humidity)
            time.sleep(1)

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure serial connection is closed
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

