import time
import sys
from gpiozero import PWMOutputDevice, GPIOZeroError

# Configuration for the fan control system
FAN_GPIO_PIN = 12
PWM_FREQUENCY = 25000

def initialize_fan():
    """Initializes the fan control pin with hardware PWM."""
    try:
        fan = PWMOutputDevice(FAN_GPIO_PIN, frequency=PWM_FREQUENCY, initial_value=0)
        return fan
    except GPIOZeroError as e:
        print(f"Error initializing fan: {e}")
        return None

def set_fan_speed(fan, speed_percentage):
    """Sets the fan speed as a percentage of maximum speed."""
    try:
        fan.value = speed_percentage / 100.0
    except Exception as e:
        print(f"Error setting fan speed: {e}")

def get_user_input():
    """Gets user input for fan speed or quit command."""
    try:
        user_input = input("Enter fan speed (0-100) or 'q' to quit: ")
        return user_input
    except KeyboardInterrupt:
        return 'q'

def main():
    """Main function to control the fan speed."""
    fan = initialize_fan()
    if fan is None:
        print("Failed to initialize fan. Exiting.")
        return

    try:
        while True:
            user_input = get_user_input()
            if user_input.lower() == 'q':
                print("Exiting program.")
                break

            try:
                fan_speed = float(user_input)
                if 0 <= fan_speed <= 100:
                    set_fan_speed(fan, fan_speed)
                    print(f"Fan speed set to {fan_speed}%")
                else:
                    print("Invalid input. Please enter a number between 0 and 100.")
            except ValueError:
                print("Invalid input. Please enter a number or 'q' to quit.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if fan:
            fan.close()
            print("Fan control resources released.")

if __name__ == "__main__":
    main()

