logger = logging.getLogger(__name__)

# Constants for Modbus register addresses (adjust based on your servo's specs)
MODBUS_CONFIG = {
    'CONTROL': {'R/W': 'W', 'Register': 0x3100, 'functioncode': 6, 'Value': {'Stop': 0x0006, 'Start': 0x000F, 'Reset': 0x0080, 'SetZero': 0x0000}},
    'STATUS': {'R/W': 'R', 'Register': 0x3000, 'functioncode': 3, 'read_length': 2},
    'OPMODE': {'R/W': 'W', 'Register': 0x3500, 'functioncode': 6, 'Value': {'Position': 1, 'Speed': 3, 'Home': 6, 'Stay': 0}},
    'VelocityCommand': {'R/W': 'W', 'Register': 0x6F00, 'functioncode': 10},
    'VelocityFeedback': {'R/W': 'R', 'Register': 0x3B00, 'functioncode': 3, 'read_length': 2},
    'PositionCommand': {'R/W': 'W', 'Register': 0x4000, 'functioncode': 10},
    'PositionFeedback': {'R/W': 'R', 'Register': 0x3700, 'functioncode': 3, 'read_length': 2},
    'CurrentCommand': {'R/W': 'W', 'Register': 0x4F00, 'functioncode': 10},
    'CurrentFeedback': {'R/W': 'R', 'Register': 0x2B00, 'functioncode': 3, 'read_length': 2},
    'FeedbackTime': {'R/W': 'R', 'Register': 0x3A00, 'functioncode': 3, 'read_length': 2},
}


class ModbusDevice:
    """Base class for Modbus devices, providing common functionalities."""

    def __init__(self, port, baudrate, timeout, unit=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.unit = unit
        self.client = None

    def connect(self):
        """Establishes a connection to the Modbus device."""
        try:
            self.client = ModbusClient(method='rtu', port=self.port, baudrate=self.baudrate, timeout=self.timeout)
            self.client.connect()
            logger.info(f"Connected to Modbus device on {self.port}")
        except serial.SerialException as e:
            logger.error(f"Failed to connect to {self.port}: {e}")
            raise

    def disconnect(self):
        """Closes the Modbus connection."""
        if self.client:
            self.client.close()
            logger.info("Disconnected from Modbus device.")

    def _read_register(self, config, count=1):
        """Generic register read function."""
        if not self.client or not self.client.is_socket_open():
            logger.warning("Modbus client not connected.")
            return None

        try:
            result = self.client.read_holding_registers(config['Register'], count, unit=self.unit)
            if result.isError():
                logger.error(f"Modbus read error: {result}")
                return None
            return result.registers
        except Exception as e:
            logger.error(f"Error reading register {config['Register']}: {e}")
            return None

    def _write_register(self, config, value):
        """Generic register write function."""
        if not self.client or not self.client.is_socket_open():
            logger.warning("Modbus client not connected.")
            return False

        try:
            result = self.client.write_single_register(config['Register'], value, unit=self.unit)
            if result.isError():
                logger.error(f"Modbus write error: {result}")
                return False
            return True
        except Exception as e:
            logger.error(f"Error writing to register {config['Register']}: {e}")
            return False


class Servo(ModbusDevice):
    """Represents a servo motor controlled via Modbus."""

    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=0.05):
        super().__init__(port, baudrate, timeout)

    def _decode_value(self, register_value, decimals=2):
        """Decodes a 32-bit register value into a float."""
        try:
            decoder = Decoder.fromRegisters(register_value[0], register_value[1], endian=Endian.Little)
            return decoder.decode_32bit_float()
        except Exception as e:
            logger.error(f"Error decoding value: {e}")
            return None

    def _encode_value(self, value):
        """Encodes a float into two 16-bit registers."""
        try:
            builder = Builder(6, endian=Endian.Little)  # 6 bytes for 32-bit float
            builder.add_32bit_float(value)
            return builder.build()
        except Exception as e:
            logger.error(f"Error encoding value: {e}")
            return None

    def set_opmode(self, opmode):
        """Sets the servo operating mode."""
        config = MODBUS_CONFIG['OPMODE']
        value = config['Value'].get(opmode)
        if value is None:
            logger.error(f"Invalid opmode: {opmode}")
            return False

        return self._write_register(config, value)

    def set_position(self, position):
        """Sets the servo position."""
        config = MODBUS_CONFIG['PositionCommand']
        encoded_value = self._encode_value(position)
        if encoded_value:
            return self._write_register(config, encoded_value[0]) and self._write_register(config, encoded_value[1])
        return False

    def get_feedback_value(self, feedback_type):
        """Retrieves feedback values from the servo."""
        config = MODBUS_CONFIG.get(feedback_type)
        if not config:
            logger.error(f"Invalid feedback type: {feedback_type}")
            return None

        if config['R/W'] == 'R':
            register_value = self._read_register(config, config.get('read_length', 1))
            if register_value:
                return self._decode_value(register_value)
            return None

        logger.error(f"Invalid feedback type: {feedback_type}. Can only read.")
        return None


if __name__ == '__main__':
    servo = Servo(port='/dev/serial0', baudrate=115200, timeout=0.05)
    try:
        servo.connect()
        # Example usage:
        if servo.set_opmode('Position'):
            time.sleep(1)
            position = servo.get_feedback_value('PositionFeedback')
            if position is not None:
                logger.info(f"Servo position: {position}")

    except Exception as e:
        logger.exception(f"An error occurred: {e}")
    finally:
        servo.disconnect()

