from flask import Flask, request, jsonify
from gpiozero import OutputDevice
import atexit
import json
import os

# Flask application setup
app = Flask(__name__)

# GPIO pin for the relay (BCM numbering)
RELAY_PIN = 23

# Initialize the relay control
try:
    relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
except Exception as e:
    print(f"Error initializing relay: {e}")
    exit(1)  # Exit if relay initialization fails

# Function to handle relay state changes
def set_relay_state(state):
    """Sets the relay state based on the provided input."""
    try:
        if state == 'on':
            relay.on()
        elif state == 'off':
            relay.off()
        else:
            raise ValueError("Invalid state. Must be 'on' or 'off'.")
        return True
    except Exception as e:
        print(f"Error setting relay state: {e}")
        return False

# Route for handling relay control requests
@app.route('/relay', methods=['POST'])
def relay_control():
    """Handles POST requests to control the relay."""
    try:
        # Parse the JSON payload from the request
        request_data = request.get_json()

        # Validate the request data
        if not request_data or 'state' not in request_data:
            return jsonify({'error': 'Invalid request: Missing "state" key'}), 400

        # Set the relay state based on the request
        if set_relay_state(request_data['state']):
            return jsonify({'status': 'Relay state changed'}), 200
        else:
            return jsonify({'error': 'Failed to change relay state'}), 500

    except json.JSONDecodeError:
        return jsonify({'error': 'Invalid JSON payload'}), 400
    except Exception as e:
        print(f"Error processing request: {e}")
        return jsonify({'error': 'Internal server error'}), 500

# Cleanup function to release GPIO resources
def cleanup():
    """Releases GPIO resources."""
    print("Cleaning up GPIO...")
    relay.close()
    print("GPIO cleanup complete.")

# Register the cleanup function to be called on exit
atexit.register(cleanup)

# Run the Flask app
if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    except Exception as e:
        print(f"Error running the Flask app: {e}")

