        return config
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        return None
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON format in configuration file: {config_file}")
        return None

def read_rtc_time(bus):
    """Reads time from the DS3231 RTC module."""
    try:
        data = bus.read_i2c_block_data(0x68, 0x00, 7)
        seconds = bcd_to_decimal(data[0] & 0x7F)
        minutes = bcd_to_decimal(data[1] & 0x7F)
        hours = bcd_to_decimal(data[2] & 0x3F)
        return datetime.time(hours, minutes, seconds)
    except Exception as e:
        logging.warning(f"Failed to read RTC time: {e}. Using system time.")
        return None

def bcd_to_decimal(bcd):
    """Converts Binary Coded Decimal (BCD) to decimal."""
    return (bcd >> 4) * 10 + (bcd & 0x0F)

def transmit_rf_code(code, gpio_pin, transmission_repeat):
    """Transmits an RF code using the GPIO pin."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(gpio_pin, GPIO.OUT)
        for _ in range(transmission_repeat):
            for bit in code:
                if bit == '1':
                    GPIO.output(gpio_pin, GPIO.HIGH)
                else:
                    GPIO.output(gpio_pin, GPIO.LOW)
                time.sleep(0.001)  # 1ms pulse
            time.sleep(0.01)  # 10ms gap
    except Exception as e:
        logging.error(f"Error transmitting RF code: {e}")
        return False
    finally:
        GPIO.cleanup(gpio_pin)
    return True

