# radiation_alarm_rpizero.py
# Reads radiation data from a UART sensor and triggers an alarm on a GPIO pin.
# Optimized for Raspberry Pi Zero W in an industrial automation context.

import serial
import time
import RPi.GPIO as GPIO

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_GPIO_PIN = 18
RADIATION_THRESHOLD = 50.0  # µSv/h

def initialize_serial(port, baud, timeout):
    """Initializes and returns a serial port object."""
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_gpio(pin):
    """Initializes the GPIO pin for the alarm."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)

def read_radiation_data(serial_port):
    """Reads a line from the serial port and returns the radiation value."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from serial port.")
        return None

def trigger_alarm(pin, radiation_level, threshold):
    """Triggers the alarm if the radiation level exceeds the threshold."""
    if radiation_level > threshold:
        GPIO.output(pin, GPIO.HIGH)  # Activate alarm
        print("Alarm triggered!")
    else:
        GPIO.output(pin, GPIO.LOW)  # Deactivate alarm

def main():
    """Main function to read radiation data and control the alarm."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        exit(1)

    initialize_gpio(ALARM_GPIO_PIN)

    try:
        while True:
            radiation_value = read_radiation_data(serial_connection)
            if radiation_value is not None:
                print(f"Radiation Level: {radiation_value} µSv/h")
                trigger_alarm(ALARM_GPIO_PIN, radiation_value, RADIATION_THRESHOLD)
            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program...")

    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Serial port closed and GPIO cleaned up.")

if __name__ == "__main__":
    main()

