import signal
import sys
from flask import Flask, Response, request, abort, jsonify
import serial

app = Flask(__name__)

# Configuration
DATA_STORE = [
    {'id': 1, 'name': 'Item 1', 'done': False},
    {'id': 2, 'name': 'Item 2', 'done': True}
]
DATA_LOCK = threading.Lock()
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 1

# Global variable to track serial port state
serial_port = None
serial_lock = threading.Lock()


class SerialCommunicator:
    """
    Manages serial communication with the USB instrument.
    Uses a context manager for resource management.
    """

    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None

    def __enter__(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            return self
        except serial.SerialException as e:
            print(f"Error opening serial port {self.port}: {e}")
            raise

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.ser and self.ser.is_open:
            self.ser.close()

    def send(self, command):
        """Sends a command to the instrument and returns the response."""
        try:
            with self as ser:
                ser.ser.write(f'{command}\n'.encode())
                response = ser.ser.readline().decode('ascii', errors='replace').strip()
                return response
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            raise

    def close(self):
        """Closes the serial port."""
        if self.ser and self.ser.is_open:
            self.ser.close()


def get_instrument_version():
    """Retrieves the instrument version information."""
    try:
        with SerialCommunicator(SERIAL_PORT, SERIAL_BAUDRATE, SERIAL_TIMEOUT) as comm:
            response = comm.send('*IDN?')
            return response
    except serial.SerialException:
        return None


def get_data():
    """Returns a copy of the data store."""
    with DATA_LOCK:
        return DATA_STORE.copy()


def get_item_by_id(item_id):
    """Retrieves an item by ID."""
    with DATA_LOCK:
        for item in DATA_STORE:
            if item['id'] == item_id:
                return item
    return None


def create_item(name, done):
    """Creates a new item and returns the created item."""
    if not isinstance(name, str) or not isinstance(done, bool):
        return None

    with DATA_LOCK:
        item_id = DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1
        new_item = {'id': item_id, 'name': name, 'done': done}
        DATA_STORE.append(new_item)
        return new_item


@app.route('/version', methods=['GET'])
def version_endpoint():
    """Endpoint to retrieve the instrument version."""
    version_info = get_instrument_version()
    if version_info:
        return Response(version_info + '\n', mimetype='text/plain')
    else:
        abort(500, "Could not retrieve instrument version.")


@app.route('/data', methods=['GET'])
def get_data_route():
    """Endpoint to retrieve all data."""
    return jsonify(get_data())


@app.route('/data/<int:item_id>', methods=['GET'])
def get_item_route(item_id):
    """Endpoint to retrieve a specific item."""
    item = get_item_by_id(item_id)
    if item:
        return jsonify(item)
    else:
        abort(404, f"Item with ID {item_id} not found.")


@app.route('/data', methods=['POST'])
def create_item_route():
    """Endpoint to create a new item."""
    try:
        request_data = request.get_json()
        if not request_data or 'name' not in request_data or 'done' not in request_data:
            abort(400, "Invalid request. 'name' and 'done' are required.")

