import json
import time
from threading import Thread
from flask import Flask, Response, request, jsonify, abort
import serial

app = Flask(__name__)
store = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "garden", "done": False}]


def open_serial(port="/dev/ttyUSB0", baud=9600):
    """Opens and returns a serial port."""
    try:
        ser = serial.Serial(port, baud, timeout=1)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def get_instrument_version(ser):
    """Queries a serial port for the instrument's version information."""
    if not ser:
        return "Serial port not initialized"

    try:
        ser.write(b"*IDN?\n")
        time.sleep(0.1)
        response = ser.readall().decode("utf-8", errors="ignore")
        return response
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return f"Serial error: {e}"
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return f"Unexpected error: {e}"


@app.route("/version")
def version():
    """Displays the instrument's version information."""
    ser = open_serial()
    version_info = get_instrument_version(ser)
    if ser:
        ser.close()
    html_output = f"<h1>Instrument Version Info</h1><pre>{version_info}</pre>"
    return Response(html_output, mimetype="text/html")


@app.route("/getdata")
def get_data():
    """Returns the current data store as JSON."""
    return jsonify(store)


@app.route("/getset/<int:item_id>")
def get_set(item_id):
    """Retrieves a specific item from the data store by ID."""
    item = next((item for item in store if item["id"] == item_id), None)
    if item:
        return jsonify(item)
    else:
        return Response("No item found with that ID\n", mimetype="text/plain", status=404)


@app.route("/getpost/<int:item_id>/<name>")
def get_post(item_id, name):
    """Adds a new item to the data store."""
    new_id = store[-1]["id"] + 1 if store else 1
    new_item = {"id": new_id, "name": name, "done": False}
    store.append(new_item)
    return jsonify(store)


@app.route("/postjson", methods=["POST", "GET"])
def post_json():
    """Handles POST requests with JSON data and returns the updated store."""
    try:
        if "application/json" in request.headers.get("Content-Type", ""):
            body = request.get_json()
        else:
            body = request.get_data().decode("utf-8") or request.form.to_dict()

        if not body:
            abort(400, "No data provided")

        if isinstance(body, dict):
            new_item = body
        elif isinstance(body, str):
            try:
                new_item = json.loads(body)
            except json.JSONDecodeError:
                abort(400, "Invalid JSON format")
        else:
            abort(400, "Unsupported data type")

        new_id = store[-1]["id"] + 1 if store else 1
        new_item["id"] = new_id
        store.append(new_item)
        return jsonify(store)

    except (KeyError, TypeError, ValueError) as e:
        abort(400, f"Invalid data: {e}")


@app.route("/postjson", methods=["POST"])
def post_json_route():
    """Handles POST requests with JSON data and returns the updated store."""
    return post_json()


@app.route("/postjson", methods=["GET"])
def get_json_route():
    """Handles GET requests and returns the current store as JSON."""
    return jsonify(store)


if __name__ == "__main__":
    app.run(debug=True, host="0.0.0.0")

